contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount, uint extraValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount) + (extraValue)); require(depositAmount <= 1000000000000000000000000000000); require(extraValue <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount + extraValue);

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint preBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect{value: extraValue}(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint postBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (reverted && postBal == preBal) ||
            (!reverted && postBal <= preBal)
        );
    }

    receive() external payable {}
}

