pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount, uint256 collectAmount, uint256 extraValue) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        extraValue = bound(extraValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount + extraValue);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 preBal;
        try c.balances(address(this)) returns (uint256 __r) { preBal = __r; } catch { return; }
        bool reverted;
        try c.Collect{value: extraValue}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 postBal;
        try c.balances(address(this)) returns (uint256 __r) { postBal = __r; } catch { return; }
        assertTrue((reverted && postBal == preBal) ||
            (!reverted && postBal <= preBal));
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount, uint256 extraValue) public {
        _run(depositAmount, collectAmount, extraValue);
    }

    receive() external payable {}
}
